(2172, 'CONTENEDOR MODEL', '2026-11-02 01:04:42', 'Consultar contenedor 1', 'SELECT c.id, c.ubicacion, c.en_funcion, a.tipo_basuras, a.cantidad\n                FROM contenedor c\n                LEFT JOIN almacenado a ON a.id_contenedor = c.id\n                WHERE c.id = ?', '[1]'),
(2173, 'CONTENEDOR MODEL', '2026-11-02 01:04:42', 'Consultar estado actual del contenedor 1', 'SELECT condicion, basura, fecha\n                FROM estado_contenedor\n                WHERE id_contenedor = ?\n                ORDER BY fecha DESC, id DESC\n                LIMIT 1', '[1]'),
(2174, 'CONTENEDOR MODEL', '2026-11-02 01:04:42', 'Consultar ultimo llenado del contenedor 1', 'SELECT llenado, fecha\n                FROM llenado\n                WHERE id_contenedor = ?\n                ORDER BY fecha DESC, id DESC\n                LIMIT 1', '[1]'),
(2175, 'CONTENEDOR MODEL', '2026-11-02 01:04:42', 'Consultar historial de estados del contenedor 1', 'SELECT condicion, basura, fecha\n                FROM estado_contenedor\n                WHERE id_contenedor = ?\n                ORDER BY fecha DESC, id DESC', '[1]'),
(2176, 'CONTENEDOR MODEL', '2026-11-02 01:04:42', 'Consultar historial de llenado del contenedor 1', 'SELECT llenado, fecha\n                FROM llenado\n                WHERE id_contenedor = ?\n                ORDER BY fecha DESC, id DESC', '[1]'),
(2177, 'CONTENEDOR MODEL', '2026-11-02 01:04:42', 'Consultar historial de vaciados del contenedor 1', 'SELECT tipos, fecha\n                FROM vaciado\n                WHERE id_contenedor = ?\n                ORDER BY fecha DESC, id DESC', '[1]'),
