(3673, 'CONTENEDOR MODEL', '2026-11-02 01:16:22', 'Listar contenedores (en_funcion y tipo de basura opcionales)', 'SELECT c.id, c.ubicacion, c.en_funcion,\n                       a.tipo_basuras, a.cantidad,\n                       e.condicion, e.basura, e.fecha AS estado_fecha,\n                       l.llenado, l.fecha AS llenado_fecha\n                FROM contenedor c\n                LEFT JOIN almacenado a ON a.id_contenedor = c.id\n                LEFT JOIN estado_contenedor e ON e.id = (\n                    SELECT e2.id FROM estado_contenedor e2\n                    WHERE e2.id_contenedor = c.id\n                    ORDER BY e2.fecha DESC, e2.id DESC LIMIT 1)\n                LEFT JOIN llenado l ON l.id = (\n                    SELECT l2.id FROM llenado l2\n                    WHERE l2.id_contenedor = c.id\n                    ORDER BY l2.fecha DESC, l2.id DESC LIMIT 1) ORDER BY c.id ASC', '[]'),
(3674, 'LOG MODEL', '2026-11-02 01:16:22', 'Insertar log de usuario para CI: 21 - Tipo: CONTENEDOR CONTROLLER', 'INSERT INTO log_user (cedula_usuario, tipo_log, texto) VALUES (?, ?, ?)', '[21,\"CONTENEDOR CONTROLLER\",\"List\\u00f3 contenedores\"]'),
(3675, 'LOG MODEL', '2026-11-02 01:16:26', 'Insertar log de usuario para CI: 21 - Tipo: AUTH CONTROLLER', 'INSERT INTO log_user (cedula_usuario, tipo_log, texto) VALUES (?, ?, ?)', '[21,\"AUTH CONTROLLER\",\"Firma de token validada correctamente\"]');
