(3831, 'RUTA MODEL', '2026-11-02 01:17:04', 'Sacar de la ruta 1 los contenedores que ya no existen', 'DELETE rc FROM ruta_contenedor rc\n                    LEFT JOIN contenedor c ON c.id = rc.id_contenedor\n                    WHERE rc.id_ruta = ? AND c.id IS NULL', '[1]'),
(3832, 'RUTA MODEL', '2026-11-02 01:17:04', 'Consultar el orden de los contenedores de la ruta 1', 'SELECT id_contenedor\n                FROM ruta_contenedor\n                WHERE id_ruta = ?\n                ORDER BY orden ASC', '[1]'),
(3833, 'RUTA MODEL', '2026-11-02 01:17:04', 'Renumerar la ruta 1', 'UPDATE ruta_contenedor\n                SET orden = ?\n                WHERE id_ruta = ? AND id_contenedor = ? AND orden <> ?', '[1,1,1,1]'),
(3834, 'RUTA MODEL', '2026-11-02 01:17:04', 'Renumerar la ruta 1', 'UPDATE ruta_contenedor\n                SET orden = ?\n                WHERE id_ruta = ? AND id_contenedor = ? AND orden <> ?', '[2,1,2,2]'),
(3835, 'RUTA MODEL', '2026-11-02 01:17:04', 'Revisar id_centro_inicio de la ruta 1', 'UPDATE ruta r\n                SET r.id_centro_inicio = NULL\n                WHERE r.id = ? AND r.id_centro_inicio IS NOT NULL\n                AND NOT EXISTS (SELECT 1 FROM centro_almacenamiento c WHERE c.id = r.id_centro_inicio)', '[1]'),
(3836, 'RUTA MODEL', '2026-11-02 01:17:04', 'Revisar id_centro_final de la ruta 1', 'UPDATE ruta r\n                SET r.id_centro_final = NULL\n                WHERE r.id = ? AND r.id_centro_final IS NOT NULL\n                AND NOT EXISTS (SELECT 1 FROM centro_almacenamiento c WHERE c.id = r.id_centro_final)', '[1]'),
(3837, 'RUTA MODEL', '2026-11-02 01:17:04', 'Consultar ruta 1', 'SELECT id, id_centro_inicio, id_centro_final\n                FROM ruta\n                WHERE id = ?', '[1]'),
(3838, 'RUTA MODEL', '2026-11-02 01:17:04', 'Consultar contenedores de la ruta 1', 'SELECT orden, id_contenedor\n                FROM ruta_contenedor\n                WHERE id_ruta = ?\n                ORDER BY orden ASC', '[1]'),
(3839, 'RUTA MODEL', '2026-11-02 01:17:04', 'Consultar tipos de basura de la ruta 1', 'SELECT a.tipo_basuras\n                FROM ruta_contenedor rc\n                INNER JOIN almacenado a ON a.id_contenedor = rc.id_contenedor\n                WHERE rc.id_ruta = ?', '[1]'),
(3840, 'RUTA MODEL', '2026-11-02 01:17:04', 'Contar contenedores de la ruta 1', 'SELECT COUNT(*) AS cantidad_contenedores\n                FROM ruta_contenedor\n                WHERE id_ruta = ?', '[1]'),
(3841, 'CENTRO MODEL', '2026-11-02 01:17:04', 'Consultar centro 1', 'SELECT id, ubicacion\n                FROM centro_almacenamiento\n                WHERE id = ?', '[1]'),
(3842, 'CENTRO MODEL', '2026-11-02 01:17:04', 'Consultar almacenamientos de los centros', 'SELECT id, id_centro, tipo_basuras, cantidad, volumen_actual\n                FROM almacenamiento_centro\n                WHERE id_centro IN (?)\n                ORDER BY id_centro ASC, id ASC', '[1]'),
(3843, 'CENTRO MODEL', '2026-11-02 01:17:04', 'Consultar centro 1', 'SELECT id, ubicacion\n                FROM centro_almacenamiento\n                WHERE id = ?', '[1]'),
(3844, 'CENTRO MODEL', '2026-11-02 01:17:04', 'Consultar almacenamientos de los centros', 'SELECT id, id_centro, tipo_basuras, cantidad, volumen_actual\n                FROM almacenamiento_centro\n                WHERE id_centro IN (?)\n                ORDER BY id_centro ASC, id ASC', '[1]'),
